from difflib import unified_diff

def find_diffs(in_grid, out_grid):
    "Return list of (row_idx, col_idx, old_val, new_val)"
    diffs = []
    for r in range(len(in_grid)):
        for c in range(len(in_grid[r])):
            if in_grid[r][c] != out_grid[r][c]:
                diffs.append((r, c, in_grid[r][c], out_grid[r][c]))
    return diffs

diffs = find_diffs(demo_in, demo_out)
print("All diffs in demo:")
for r, c, old, new in diffs:
    print(f"  Row {r}, Col {c}: {old} -> {new}")

# Group by row
from collections import defaultdict
by_row = defaultdict(list)
for r, c, old, new in diffs:
    by_row[r].append((c, old, new))

print("\nChanges by row:")
for r in sorted(by_row.keys()):
    print(f"\nRow {r}:")
    for c, old, new in sorted(by_row[r]):
        print(f"  Col {c}: {old} -> {new}")

# Look at contiguous groups of 6s in columns 1,4,7,10

def get_groups(row, cols):
    """Return list of (col_start, col_end) for contiguous 6s in given columns"""
    groups = []
    if row[cols[0]] == 6:
        start = cols[0]
        for i, c in enumerate(cols):
            if c == cols[-1] and row[c] == 6:
                end = c
                groups.append((start, end))
                break
            if row[c] != 6:
                break
        else:
            end = cols[-1]
            groups.append((start, end))
    return groups

print("Contiguous groups of 6s in cols [1,4,7,10]:")
for r in [1,5,7,9,11]:
    cols = [1,4,7,10]
    vals = [int(demo_in[r][c]) for c in cols]
    print(f"\nRow {r}, vals={vals}:")
    contiguous = []
    in_group = False
    for i, v in enumerate(vals):
        if v == 6:
            if not in_group:
                start = i
                in_group = True
        else:
            if in_group:
                contiguous.append(start)
                in_group = False
    if in_group:
        contiguous.append(start)
    print(f"  Start of contiguous 6s: {contiguous}")

